"""Plain-text absence notices for parents."""

from typing import Iterable, List
from rosterkit.models import Mark, Student
from datetime import date

Marks = Iterable[Mark]


def _check_owner(student: Student, marks: List[Mark]):
    for mark in marks:
        if mark.student_id != student.student_id:
            raise ValueError(
                f"mark belongs to {mark.student_id}"
            )


def _is_absent(mark: Mark) -> bool:
    return mark.status == "absent"


def _absences(student: Student, marks: Marks) -> List[date]:
    items = list(marks)
    _check_owner(student, items)
    days = {item.day for item in items if _is_absent(item)}
    if not days:
        raise ValueError("no absences to report")
    return sorted(days)


def _day_lines(days: List[date]) -> str:
    return "\n".join(f"- {day.isoformat()}" for day in days)


def _headline(student: Student, count: int) -> str:
    name = f"{student.first_name} {student.last_name}"
    word = "day" if count == 1 else "days"
    return f"{name} missed {count} {word} of school:"


# ---
def build_absence_notice(student: Student, marks: Marks):
    """Notice text for the student's absent days."""
    days = _absences(student, marks)
    head = _headline(student, len(days))
    body = _day_lines(days)
    return f"Dear parent or guardian,\n\n{head}\n{body}"
